declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$manager=in_array($role,['admin','director','sub_director','headteacher'],true);if(!$manager&&$role!=='department_head'){http_response_code(403);exit('Your role cannot access departments.');}$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schools[0]['id']);if(!in_array($school,array_map('intval',array_column($schools,'id')),true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];
